#include "stdafx.h"#include "TrendReadCycle.h"#include "TrendFile.h"#include "LogFile.h"KTrendReadCycle::KTrendReadCycle(){}KTrendReadCycle::~KTrendReadCycle(){}void KTrendReadCycle::MainLoop(){	CLogFile::Log ("KTrendReadCycle::MainLoop Started");	SToTrend to;	ULONG errTryingNum=0;	while( !IsStopClientService() )  // общее для всех клиентов условие	{		CLogFile::Log ("KTrendReadCycle::MainLoop_0");		Sleep(100);		memset(&to,0,sizeof(SToTrend));//clear input buffer		//# get ask buffer		DWORD	askBytesRead = 0;		BOOL isTransactionOK = ReadData( &to, sizeof(to), &askBytesRead);// read ask from pipe as char[]		CLogFile::Log ("KTrendReadCycle::MainLoop_1: isTransactionOK %d, askBytesRead %d", isTransactionOK, askBytesRead);		if ( IsStopClientService() )		{			CLogFile::Log ("KTrendReadCycle::MainLoop IsStopClientService!!!");			break;		}		if( isTransactionOK && askBytesRead > 0 )		{			errTryingNum = 0;			CLogFile::Log ("KTrendReadCycle::MainLoop_2: to.askKind %d", to.askKind);			if ( to.askKind == 5   )			{				CLogFile::Log ("KTrendReadCycle::MainLoop_21");				AskKind5( to );			}			else			{				CLogFile::Log ("KTrendReadCycle::MainLoop_22");				char ch = -55; 				DWORD	answerBytesWrite = 0;				WriteData( (LPCVOID)&ch, 1, &answerBytesWrite );				break;			}		}		else		{			CLogFile::Log ("KTrendReadCycle::MainLoop_4");			Sleep(100);			errTryingNum++;			// закрываем клиентский луп по ошибкам чтения			if( errTryingNum > 5 * 4) 			{				break;			}		}	}}// Обработка запроса 5// Запрос графической информации// При ошибке код завершения -77extern CTrendFile theTrend;bool KTrendReadCycle::AskKind5( SToTrend& to ){	CLogFile::Log ("KTrendReadCycle::AskKind5_00: to.askKind %d, to.nCount %d", to.askKind, to.nCount);	DWORD dwOutSize = sizeof(SFromTrend5)+to.nCount*2*(to.nPoint+1)*sizeof(_Sxy);	CLogFile::Log ("KTrendReadCycle::AskKind5_01: dwOutSize %d", (int)dwOutSize);	char* outBuffer = (char *)calloc( dwOutSize , sizeof( char ) );	char chReturn = 0;	if ( outBuffer == NULL ) chReturn = -70; 	else	{		int nReturn = theTrend.FromTrend( &to, outBuffer );		CLogFile::Log ("KTrendReadCycle::AskKind5_1: nReturn %d", nReturn);		if ( nReturn != 0 )			chReturn = -70-nReturn;	}	DWORD answerBytesWrite;	if ( chReturn != 0 )		WriteData( (LPCVOID)&chReturn, 1, &answerBytesWrite );	else	{		CLogFile::Log ("KTrendReadCycle::AskKind5_11: dwOutSize %d, to.nCount %d, to.nPoint %d", dwOutSize, to.nCount, to.nPoint);		WriteData( outBuffer, dwOutSize, &answerBytesWrite );	}	if ( outBuffer != NULL ) free(outBuffer);	CLogFile::Log ("KTrendReadCycle::AskKind5_2: chReturn %d", chReturn);	return chReturn == 0;}